progressive_examples.raw_code:
// Khai báo trạng thái đơn hàng cần kiểm tra
const orderStatusCode = "SHIPPING";
let statusMessage = "";

// Kiểm tra trạng thái bằng cấu trúc switch-case
switch (orderStatusCode) {
  case "PENDING":
    statusMessage = "Đơn hàng của bạn đã được ghi nhận và chờ xác nhận.";
    break;
  case "PROCESSING":
    statusMessage = "Đơn hàng đang được đóng gói tại kho.";
    break;
  case "SHIPPING":
    statusMessage = "Đơn hàng đang trên đường giao đến bạn.";
    break;
  case "DELIVERED":
    statusMessage = "Giao hàng thành công!";
    break;
}

console.log(statusMessage);

const statusCode = "PROCESSING";
let statusGroupMessage = "";

switch (statusCode) {
  // Gom nhóm các trạng thái ở bước chuẩn bị
  case "PENDING":
  case "PROCESSING":
  case "APPROVED":
    statusGroupMessage = "Đơn hàng đang trong giai đoạn xử lý nội bộ.";
    break;

  // Gom nhóm các trạng thái vội/đang vận chuyển
  case "SHIPPING":
  case "IN_TRANSIT":
    statusGroupMessage = "Đơn hàng đang được vận chuyển bởi đối tác giao hàng.";
    break;

  case "DELIVERED":
    statusGroupMessage = "Đơn hàng đã giao thành công.";
    break;

  case "CANCELLED":
  case "REFUNDED":
    statusGroupMessage = "Đơn hàng đã hủy hoặc được hoàn tiền.";
    break;

  // Xử lý khi mã trạng thái không khớp với bất kỳ case nào ở trên
  default:
    statusGroupMessage = "[WARNING] Mã trạng thái đơn hàng không hợp lệ trên hệ thống.";
    break;
}

console.log(statusGroupMessage);

const regionCode = "SUBURBAN"; // Khu vực: INNER_CITY (Nội thành), SUBURBAN (Ngoại thành), PROVINCIAL (Tỉnh)
const isExpress = true; // Giao hàng hỏa tốc

let baseShippingFee = 0;
let estimatedDays = 0;
let isValidRegion = true;

// Xử lý mức phí cơ bản và số ngày giao theo khu vực
switch (regionCode) {
  case "INNER_CITY":
    baseShippingFee = 15000;
    estimatedDays = 1;
    break;
  case "SUBURBAN":
    baseShippingFee = 30000;
    estimatedDays = 2;
    break;
  case "PROVINCIAL":
    baseShippingFee = 50000;
    estimatedDays = 4;
    break;
  default:
    isValidRegion = false;
    console.log("[ERROR] Đơn hàng không thể tính phí do vùng giao hàng không hợp lệ.");
    break;
}

// Nếu khu vực hợp lệ, tiến hành tính toán phụ phí hỏa tốc nếu có
if (isValidRegion) {
  let totalShippingFee = baseShippingFee;

  if (isExpress) {
    totalShippingFee = baseShippingFee + 20000;
    estimatedDays = estimatedDays - 1;
    if (estimatedDays < 1) {
      estimatedDays = 1;
    }
  }

  console.log("--- THÔNG TIN VẬN CHUYỂN --- ");
  console.log("Khu vực giao:", regionCode);
  console.log("Tổng phí vận chuyển:", totalShippingFee, "VNĐ");
  console.log("Thời gian giao dự kiến:", estimatedDays, "ngày");
}

